|本姓 = [[越智氏|越智]][[宿禰]]（[[物部氏|物部姓]]?）?{{Sfn|太田|1934|p=1389}}<br/>伊予凡直?{{Sfn|太田|1934|p=1389}}<br/>
|家祖 = [[河野玉澄|越智玉澄]]<br/>河野親経{{Sfn|太田|1934|p=1389}}
|種別 = [[高家]]<br/>[[武家]]
